{"content": "<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>طبقات الأرض الجيولوجية</title>
<style>
  :root{
    --crust:#4c5b6a;
    --mantle:#e85d04;
    --outer:#f4a11b;
    --inner:#ffd60a;
    --ink:#1f2933;
    --ink-soft:#5b6672;
    --line:#e6ebf1;
    --card:#ffffff;
    --accent:#0f766e;
    --shadow:0 12px 34px rgba(15,23,42,.10);
    --radius:16px;
    --maxw:1000px;
  }

  *{box-sizing:border-box;}
  html{scroll-behavior:smooth;}

  body{
    margin:0;
    font-family:"Segoe UI","Noto Naskh Arabic","Geeza Pro","Tahoma",system-ui,sans-serif;
    color:var(--ink);
    line-height:1.8;
    background:
      radial-gradient(1100px 520px at 50% -10%, #dcefe9 0%, rgba(220,239,233,0) 60%),
      linear-gradient(180deg,#f3f8f5 0%,#ffffff 45%);
    background-attachment:fixed;
    -webkit-font-smoothing:antialiased;
    padding-bottom:40px;
  }

  .wrap{max-width:var(--maxw);margin:0 auto;padding:0 20px;}

  /* ---------- Header ---------- */
  header{
    text-align:center;
    padding:34px 0 8px;
  }
  .badge{
    display:inline-flex;align-items:center;gap:8px;
    background:var(--card);border:1px solid var(--line);
    padding:6px 14px;border-radius:999px;font-size:.85rem;
    color:var(--ink-soft);box-shadow:var(--shadow);margin-bottom:14px;
  }
  h1{
    margin:0 auto 8px;font-size:2.1rem;line-height:1.3;font-weight:800;
    background:linear-gradient(180deg,#0f766e,#0b4f48);
    -webkit-background-clip:text;background-clip:text;color:transparent;
    max-width:760px;
  }
  .sub{
    margin:0 auto;color:var(--ink-soft);font-size:1rem;max-width:680px;
  }

  /* ---------- Stage (diagram + panel) ---------- */
  .stage{
    display:grid;grid-template-columns:1.05fr 1fr;gap:26px;
    margin-top:26px;align-items:start;
  }

  .diagram{
    background:var(--card);border:1px solid var(--line);
    border-radius:var(--radius);box-shadow:var(--shadow);
    padding:18px;position:relative;
  }
  .diagram svg{width:100%;height:auto;display:block;}
  .diagram .note{
    text-align:center;color:var(--ink-soft);font-size:.78rem;margin-top:6px;
  }

  /* SVG interactivity */
  .layer{cursor:pointer;transition:filter .2s ease,opacity .2s ease;}
  .layer.active{filter:drop-shadow(0 0 7px rgba(255,255,255,.55));stroke:#ffffff;stroke-width:2.5;}
  .lbl{
    font-family:inherit;fill:#243038;font-size:14px;font-weight:700;
    transition:fill .2s ease,font-weight .2s ease;
  }
  .lbl.active{fill:var(--accent);}
  .leader{stroke:#9aa6b2;stroke-width:1.4;}
  .leader.active{stroke:var(--accent);stroke-width:1.8;}

  /* ---------- Panel ---------- */
  .panel{display:flex;flex-direction:column;gap:16px;}

  .chips{display:flex;flex-wrap:wrap;gap:10px;}
  .chip{
    display:inline-flex;align-items:center;gap:9px;
    border:1px solid var(--line);background:var(--card);
    padding:9px 16px;border-radius:999px;cursor:pointer;
    font-size:.9rem;font-weight:700;color:var(--ink);
    font-family:inherit;transition:all .16s ease;box-shadow:var(--shadow);
  }
  .chip .dot{width:13px;height:13px;border-radius:50%;flex:none;border:1px solid rgba(0,0,0,.12);}
  .chip:hover{transform:translateY(-2px);}
  .chip[aria-pressed="true"]{
    color:#fff;border-color:transparent;box-shadow:0 8px 18px rgba(15,23,42,.18);
  }
  .chip[aria-pressed="true"] .dot{border-color:rgba(255,255,255,.5);}

  .detail{
    background:var(--card);border:1px solid var(--line);
    border-top:5px solid var(--accent);
    border-radius:var(--radius);box-shadow:var(--shadow);
    padding:22px 24px;min-height:270px;
    transition:border-color .2s ease;
  }
  .detail h2{
    margin:0;font-size:1.4rem;display:flex;align-items:center;gap:12px;
  }
  .detail h2 .ico{
    width:40px;height:40px;border-radius:11px;flex:none;
    display:grid;place-items:center;font-size:20px;color:#fff;
    box-shadow:0 5px 14px rgba(15,23,42,.2);
  }
  .grid{
    display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:18px 0;
  }
  .field{
    background:#f7faf8;border:1px solid var(--line);
    border-radius:12px;padding:12px 14px;
  }
  .field .k{
    font-size:.72rem;letter-spacing:.03em;font-weight:700;
    color:var(--ink-soft);text-transform:uppercase;margin-bottom:5px;
    display:flex;align-items:center;gap:6px;
  }
  .field .v{font-size:.98rem;font-weight:600;color:var(--ink);}
  .fact{
    background:linear-gradient(180deg,#f0faf7,#ffffff);
    border:1px dashed #bfe3d8;border-radius:12px;
    padding:13px 16px;font-size:.95rem;color:#134e44;
  }
  .fact b{color:var(--accent);}

  /* ---------- Footer ---------- */
  footer{
    text-align:center;color:var(--ink-soft);font-size:.82rem;margin-top:34px;
  }

  /* ---------- Reveal animation ---------- */
  .reveal{opacity:0;transform:translateY(14px);animation:rise .6s ease forwards;}
  .d1{animation-delay:.05s;}
  .d2{animation-delay:.15s;}
  .d3{animation-delay:.25s;}
  @keyframes rise{to{opacity:1;transform:none;}}

  /* ---------- Responsive ---------- */
  @media (max-width:820px){
    .stage{grid-template-columns:1fr;}
    h1{font-size:1.7rem;}
    .grid{grid-template-columns:1fr;}
    .detail{min-height:auto;}
  }
</style>
</head>
<body>

  <div class="wrap">
    <header class="reveal">
      <div class="badge">🪨 الجيولوجيا · عرض بصري</div>
      <h1>طبقات الأرض الجيولوجية</h1>
      <p class="sub">من القشرة الرقيقة إلى النواة السخينة — استكشف بنية كوكبنا من الخارج إلى الداخل.</p>
    </header>

    <section class="stage">
      <!-- ===== Diagram ===== -->
      <div class="diagram reveal d1">
        <svg viewBox="0 0 460 430" role="img" aria-label="مقطع عرضي يوضح طبقات الأرض: القشرة، الوشاح، النواة الخارجية، والنواة الداخلية">
          <defs>
            <radialGradient id="mantleG" cx="42%" cy="38%" r="75%">
              <stop offset="0%" stop-color="#ff8a3d"/>
              <stop offset="100%" stop-color="#c94e00"/>
            </radialGradient>
            <radialGradient id="outerG" cx="45%" cy="40%" r="75%">
              <stop offset="0%" stop-color="#ffd977"/>
