            </radialGradient>
            <radialGradient id="innerG" cx="45%" cy="40%" r="70%">
              <stop offset="0%" stop-color="#fff7bf"/>
              <stop offset="100%" stop-color="#f2c200"/>
            </radialGradient>
          </defs>

          <!-- atmosphere hint -->
          <circle cx="230" cy="215" r="197" fill="none" stroke="#9cc7ea" stroke-width="7" opacity="0.45"/>

          <!-- layers (outer -> inner) -->
          <circle class="layer" data-layer="crust"  cx="230" cy="215" r="185" fill="var(--crust)"/>
          <circle class="layer" data-layer="mantle" cx="230" cy="215" r="170" fill="url(#mantleG)"/>
          <circle class="layer" data-layer="outer"  cx="230" cy="215" r="98"  fill="url(#outerG)"/>
          <circle class="layer" data-layer="inner"  cx="230" cy="215" r="46"  fill="url(#innerG)"/>

          <!-- leaders + labels -->
          <line class="leader" data-layer="crust"  x1="230" y1="24"  x2="230" y2="31"/>
          <text class="lbl" data-layer="crust"  x="230" y="20" text-anchor="middle">القشرة</text>

          <line class="leader" data-layer="mantle" x1="404" y1="78"  x2="372" y2="150"/>
          <text class="lbl" data-layer="mantle" x="452" y="74" text-anchor="end">الوشاح</text>

          <line class="leader" data-layer="outer"  x1="70"  y1="372" x2="150" y2="258"/>
          <text class="lbl" data-layer="outer"  x="14"  y="392" text-anchor="start">النواة الخارجية</text>

          <line class="leader" data-layer="inner"  x1="418" y1="372" x2="252" y2="238"/>
          <text class="lbl" data-layer="inner"  x="452" y="392" text-anchor="end">النواة الداخلية</text>
