        <div class="note">ملاحظة: السماكات مُمهَّدة لأغراض الوضوح، وهي غير مطابقة للمقياس.</div>
      </div>

      <!-- ===== Panel ===== -->
      <div class="panel">
        <div class="chips reveal d2" role="group" aria-label="اختيار الطبقة">
          <button class="chip" data-layer="crust"  aria-pressed="false"><span class="dot" style="background:var(--crust)"></span>القشرة</button>
          <button class="chip" data-layer="mantle" aria-pressed="false"><span class="dot" style="background:var(--mantle)"></span>الوشاح</button>
          <button class="chip" data-layer="outer"  aria-pressed="false"><span class="dot" style="background:var(--outer)"></span>النواة الخارجية</button>
          <button class="chip" data-layer="inner"  aria-pressed="false"><span class="dot" style="background:var(--inner)"></span>النواة الداخلية</button>
        </div>

        <article class="detail reveal d3" id="detail" aria-live="polite"></article>
      </div>
    </section>

    <footer>
      طبقات الأرض الجيولوجية · عرض بصري مستقل — القشرة، الوشاح، النواة.
    </footer>
  </div>

  <script>
    (function () {
      var DATA = {
        crust: {
          name: "القشرة",
          color: "var(--crust)",
          icon: "⛰️",
          depth: "0 – ‎~70 كم",
          comp: "صخور سيليكات خفيفة؛ قشرة محيطية (بازلت) وقارية (غرانيت).",
          temp: "‎~20 – 400°م",
          fact: "الطبقة الأرقّ على الإطلاق، وتُشكّل أقلّ من 1% من نصف قطر الأرض."
        },
        mantle: {
          name: "الوشاح",
          color: "var(--mantle)",
          icon: "🔥",
          depth: "‎~70 – 2,900 كم",
          comp: "صخور سيليكات غنية بالحديد والمغنيسيوم (أوليفين، بيروكسين)؛ صلبة لكنها تتدفّك ببطء شديد.",
          temp: "‎~500 – 4,000°م",
          fact: "يضمّ «الأسثينوسفير» الذي تدور فوقه الصفائح التكتونية وتسبّب الزلازل والبراكين."
        },
        outer: {
          name: "النواة الخارجية",
          color: "var(--outer)",
          icon: "🌀",
          depth: "‎~2,900 – 5,150 كم",
          comp: "حديد ونيكل في حالة سائلة.",
          temp: "‎~4,000 – 5,000°م",
          fact: "تُشكّل حركتها الدوّارة «دينامو» جيويًّا تولّد المجال المغناطيسي الذي يحمي الأرض."
        },
        inner: {
          name: "النواة الداخلية",
          color: "var(--inner)",
          icon: "☀️",
          depth: "‎~5,150 – 6,371 كم",
          comp: "حديد ونيكل صلب رغم حرارتها الهائلة، بسبب الضغط الشديد.",
          temp: "‎~5,000 – 6,000°م",
          fact: "حرارتها تُقارب حرارة سطح الشمس، ومع ذلك تبقى صلبة كالمعدن."
        }
      };

      var detail = document.getElementById("detail");
      var chips = Array.prototype.slice.call(document.querySelectorAll(".chip"));
      var layerEls = Array.prototype.slice.call(document.querySelectorAll(".layer"));
      var labelEls = Array.prototype.slice.call(document.querySelectorAll("[data-layer].lbl"));
      var leaderEls = Array.prototype.slice.call(document.querySelectorAll("[data-layer].leader"));

      function render(id) {
        var d = DATA[id];
        detail.style.borderTopColor = d.color;
        detail.innerHTML =
          '<h2><span class="ico" style="background:' + d.color + '">' + d.icon + "</span>" + d.name + "</h2>" +
          '<div class="grid">' +
            '<div class="field"><div class="k">📏 العمق</div><div class="v">' + d.depth + "</div></div>" +
            '<div class="field"><div class="k">🌡️ الحرارة</div><div class="v">' + d.temp + "</div></div>" +
          "</div>" +
          '<div class="field" style="margin-bottom:14px"><div class="k">🧪 التركيب</div><div class="v">' + d.comp + "</div></div>" +
          '<div class="fact"><b>معلومة:</b> ' + d.fact + "</div>";
      }

      function select(id) {
        render(id);
        chips.forEach(function (c) {
          c.setAttribute("aria-pressed", c.getAttribute("data-layer") === id ? "true" : "false");
          if (c.getAttribute("data-layer") === id) {
            c.style.background = DATA[id].color;
          } else {
            c.style.background = "";
          }
        });
        layerEls.forEach(function (el) {
          el.classList.toggle("active", el.getAttribute("data-layer") === id);
        });
        labelEls.forEach(function (el) {
          el.classList.toggle("active", el.getAttribute("data-layer") === id);
        });
        leaderEls.forEach(function (el) {
          el.classList.toggle("active", el.getAttribute("data-layer") === id);
        });
      }

      chips.forEach(function (c) {
        c.addEventListener("click", function () { select(c.getAttribute("data-layer")); });
      });
      layerEls.forEach(function (el) {
        el.addEventListener("click", function () { select(el.getAttribute("data-layer")); });
      });

      select("mantle"); // default
    })();
  </script>
</body>
</html>
