private suspend fun collectExecutorThreadIds(executor: ExecutorService, threadCount: Int): List<Int> {
    val threadIds = mutableListOf<Int>()
    val latch = CountDownLatch(threadCount)
    repeat(threadCount) {
        executor.execute {
            synchronized(threadIds) { threadIds.add(Process.myTid()) }
            latch.countDown()
        }
    }
    withContext(Dispatchers.IO) {
        latch.await()
    }
    return threadIds
}
