            volumeKeyEventFlow.tryEmit(keyCode)
            return true
        }
        return super.onKeyDown(keyCode, event)
    }

    fun registerVideoToggleReceiver() {
        ContextCompat.registerReceiver(this, recordingReceiver, IntentFilter(ACTION_TOGGLE_VIDEO), ContextCompat.RECEIVER_NOT_EXPORTED)
