private fun snapExposureToFlickerPeriod(exposureTimeNs: Long, flickerHz: Int): Long {
    val period = if (flickerHz == 50) 10_000_000L else 8_333_333L
    return maxOf(1L, Math.round(exposureTimeNs.toDouble() / period) * period)
}

private suspend fun collectExecutorThreadIds(executor: ExecutorService, threadCount: Int): List<Int> {
    val threadIds = mutableListOf<Int>()
    val latch = CountDownLatch(threadCount)
    repeat(threadCount) {
        executor.execute {
            synchronized(threadIds) { threadIds.add(Process.myTid()) }
            latch.countDown()
        }
    }
    withContext(Dispatchers.IO) {
        latch.await()
    }
    return threadIds
}

