_DIAGONAL = ((1, 1), (1, -1), (-1, 1), (-1, -1))


def _parse_fen(fen):
    """Parse FEN into (board, turn, rights).

    board maps (file, rank) with file 0-7 (a-h) and rank 1-8 to a
    piece character. turn is 'w' or 'b'. rights is a set drawn from
    'KQkq' parsed from the castling field. En-passant/halfmove/
    fullmove fields are ignored.
    """
    parts = fen.strip().split()
    if len(parts) < 2:
        raise ValueError("FEN must have at least placement and active color fields")
    board = {}
    for i, row in enumerate(parts[0].split('/')):
        rank = 8 - i
        file = 0
        for ch in row:
            if ch.isdigit():
                file += int(ch)
            else:
                if ch not in _PIECES:
                    raise ValueError("bad piece char %r in FEN placement" % ch)
                board[(file, rank)] = ch
                file += 1
        if file != 8:
            raise ValueError("FEN row does not span 8 files: %r" % row)
    turn = parts[1]
    if turn not in 'wb':
        raise ValueError("bad active color in FEN: %r" % turn)
    if len(parts) >= 3 and parts[2] != '-':
        rights = {c for c in parts[2] if c in _CASTLING_RIGHTS}
    else:
        rights = set()
    return board, turn, rights


def _sq(f, r):
    return chr(ord('a') + f) + str(r)


def _is_attacked(board, f, r, by):
    """True if square (f, r) is attacked by any piece of color `by`."""
    pawn = 'P' if by == 'w' else 'p'
    knight = 'N' if by == 'w' else 'n'
    king = 'K' if by == 'w' else 'k'
    rook = 'R' if by == 'w' else 'r'
    bishop = 'B' if by == 'w' else 'b'
    queen = 'Q' if by == 'w' else 'q'

    # Pawns attack diagonally forward: a white pawn at (x, r-1)
    # attacks (f, r); a black pawn at (x, r+1) does.
    pawn_dr = -1 if by == 'w' else 1
    for df in (-1, 1):
        if board.get((f + df, r + pawn_dr)) == pawn:
            return True

    for df, dr in _KNIGHT_DELTAS:
        if board.get((f + df, r + dr)) == knight:
            return True

    for df, dr in _KING_DELTAS:
        if board.get((f + df, r + dr)) == king:
            return True

    for df, dr in _ORTHOGONAL + _DIAGONAL:
        nf, nr = f + df, r + dr
        while 0 <= nf < 8 and 1 <= nr <= 8:
            piece = board.get((nf, nr))
            if piece is not None:
                if df == 0 or dr == 0:
