    attacked square, and not ending on one. (The square the rook
    crosses is not required to be safe.)
    """
    if not rights:
        return []
    rank = 1 if turn == 'w' else 8
    king = 'K' if turn == 'w' else 'k'
    rook = 'R' if turn == 'w' else 'r'
    opp = 'b' if turn == 'w' else 'w'
    home = (4, rank)
    if board.get(home) != king:
        return []
    if _is_attacked(board, 4, rank, opp):  # castling out of check
        return []
    moves = []
    if (turn == 'w' and 'K' in rights) or (turn == 'b' and 'k' in rights):
        if (board.get((7, rank)) == rook
                and (5, rank) not in board and (6, rank) not in board
                and not _is_attacked(board, 5, rank, opp)
                and not _is_attacked(board, 6, rank, opp)):
